/**
 * The Poisoned Feast — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { POISONED_FEAST_TEMPLATE } from '../poisoned-feast';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Poisoned Feast — template structure", () => {
  it('carries its identity', () => {
    expect(POISONED_FEAST_TEMPLATE.id).toBe('encounter.town.poisoned_feast');
    expect(POISONED_FEAST_TEMPLATE.reach).toBe('eye');
    expect(POISONED_FEAST_TEMPLATE.rarityTier).toBe(2);
    expect(POISONED_FEAST_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = POISONED_FEAST_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['feast.settle_the_dregs', 'feast.rouse_the_stricken']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['life', 'matter']);
  });

  it('step 1 deals the authored hand', () => {
    const step = POISONED_FEAST_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['feast.show_the_last_hour', 'feast.cool_a_hot_grudge']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['time']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(POISONED_FEAST_TEMPLATE.settings).toEqual(['urban']);
    expect(POISONED_FEAST_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(POISONED_FEAST_TEMPLATE.consequenceDraw).toEqual(['secret', 'story_seed']);
    expect(POISONED_FEAST_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.poisoned_feast',
          reach: 'eye',
          rarityTier: 2,
        }),
        POISONED_FEAST_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
